// ── scripted model ───────────────────────────────────────────────────────────
let narrationText = NATIVE_PROSE
let witnessMode: 'accept' | 'refuse' = 'accept'

function englishCopyFor(request: Row): string {
  if (witnessMode === 'refuse') return JSON.stringify({ player: '', prose: '' })
  const user = String((request.messages || []).find((m: Row) => m.role === 'user')?.content || '')
  const prose = /<prose>\n([\s\S]*?)\n<\/prose>/u.exec(user)?.[1] ?? ''
  const player = /<player>\n([\s\S]*?)\n<\/player>/u.exec(user)?.[1]
  const body: Row = {}
  if (player !== undefined) body.player = `EN: ${player}`
  body.prose = `EN: ${prose}`
  return JSON.stringify(body)
}

/** The scripted single-shot model: the witness copy, or the hygiene rewrite. */
async function scriptedCallLLM(request: Row): Promise<string> {
  if (request.purpose === 'witness_copy') {
    push('witnessCalls', clone(request))
    return englishCopyFor(request)
  }
  push('repairCalls', clone(request))
  const message = String(request.messages?.[0]?.content || '')
  const marker = message.lastIndexOf('Story prose:\n')
  return marker >= 0 ? message.slice(marker + 'Story prose:\n'.length) : narrationText
}

