function normalize(value: any): any {
  if (value instanceof ObjectId) return value.toHexString()
  if (value instanceof Date) return '<date>'
  if (Array.isArray(value)) return value.map(normalize)
  if (typeof value === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(value)) return '<uuid>'
  if (value && typeof value === 'object') {
    const out: Row = {}
    // JSON drops `undefined` keys, and the frozen snapshot was generated as
    // JSON; skip them so the in-memory object compares to its serialized form.
    for (const [key, entry] of Object.entries(value)) if (entry !== undefined) out[key] = normalize(entry)
    return out
  }
  return value
}

let pass = 0
let fail = 0
async function check(label: string, fn: () => Promise<void> | void) {
  try {
    await fn()
    pass++
    console.log(`  ok   ${label}`)
  } catch (err) {
    fail++
    console.log(`  FAIL ${label}\n       ${(err as Error).message}`)
  }
}

const eventRow = () => events.rows.find((row) => row._id.equals(eventId))!
const lastEventWrite = () => [...writes].reverse().find((write) => write.collection === 'events')!
const eventUpdate = () => lastEventWrite().update
const witnessSet = () => eventUpdate().$set?.['data.witness']
const witnessStatusSet = () => eventUpdate().$set?.['data.witness_status']
const witnessUnset = () => eventUpdate().$unset?.['data.witness'] !== undefined
const statusUnset = () => eventUpdate().$unset?.['data.witness_status'] !== undefined

