// ── 1. an accepted replay reads one English view everywhere ─────────────────
await check('replay accepted: every extractor reads the English copy and the witness is stored', async () => {
  reset({ replyLanguage: 'pt' })
  await memoryService.replayEvent(String(eventId), String(playerId))

  assert.ok(rec.narrationCalls.length === 1, 'one narration call')
  assert.ok(rec.witnessCalls.length === 1, 'the copy is made once')
  assert.equal(rec.witnessCalls[0].temperature, 0)
  // §8: one glossary builder — every card, present, persona, protagonist AND a
  // person the place graph alone knows.
  assert.ok(rec.witnessCalls[0].messages[0].content.includes('Vane'), 'the shared glossary carries graph-only people')

  const englishProse = `EN: ${REPLAY_NATIVE}`
  const englishPlayer = `EN: ${NATIVE_PLAYER}`
  // The extractors read the English prose and player text.
  for (const call of rec.extractorCalls) {
    assert.equal(call.narrative, englishProse)
    assert.equal(call.opts.playerInput, englishPlayer)
    assert.deepEqual(call.opts.choiceLanguage, {
      name: 'Brazilian Portuguese',
      narrative: REPLAY_NATIVE,
      playerInput: NATIVE_PLAYER,
    })
  }
  assert.equal(rec.codexCalls[0].playerInput, englishPlayer)
  assert.equal(rec.codexCalls[0].aiResponse, englishProse)
  assert.equal(rec.endpointCalls[0].playerInput, englishPlayer)
  assert.equal(rec.entityCalls[0].prose, englishProse)

  // The event and the new variant carry the copy; native display text stays.
  assert.equal(eventUpdate().$set['data.ai_response'], REPLAY_NATIVE)
  assert.equal(witnessSet().lang, 'pt')
  assert.equal(witnessSet().ai_response, englishProse)
  assert.equal(witnessSet().player_input, englishPlayer)
  assert.deepEqual(witnessSet().choices, ENGLISH_CHOICES)
  const variant = eventUpdate().$set['data.replay_variants'].at(-1)
  assert.equal(variant.narrative, REPLAY_NATIVE)
  assert.equal(variant.witness.ai_response, englishProse)
  assert.deepEqual(variant.choices, NATIVE_CHOICES)
  assert.deepEqual(variant.witness.choices, ENGLISH_CHOICES)
  assert.equal('witness_status' in variant, false)

  // The memory curator reads the same view.
  assert.equal(rec.curationJobs[0].playerInput, englishPlayer)
  assert.equal(rec.curationJobs[0].aiResponse, englishProse)
})

// ── 2. a refused copy reads native on both sides ────────────────────────────
await check('replay refused: both extractors read native, the event witness is cleared and marked', async () => {
  reset({ replyLanguage: 'pt', eventWitness: { lang: 'pt', ai_response: 'OLD ENGLISH', player_input: 'OLD PLAYER', choices: [] } })
  witnessMode = 'refuse'
  await memoryService.replayEvent(String(eventId), String(playerId))

  for (const call of rec.extractorCalls) {
    assert.ok(call.narrative.includes('Mara ergue'), 'refused: the new native prose, never the old witness')
    assert.equal(call.opts.playerInput, NATIVE_PLAYER, 'refused: native player, never the old witness')
  }
  assert.equal(rec.codexCalls[0].playerInput, NATIVE_PLAYER)
  assert.ok(rec.endpointCalls[0].prose.includes('Mara ergue'))
  assert.equal(witnessUnset(), true, 'data.witness is unset')
  assert.equal(witnessStatusSet(), 'failed')
  const variant = eventUpdate().$set['data.replay_variants'].at(-1)
  assert.equal(variant.witness_status, 'failed')
  assert.equal('witness' in variant, false)
  assert.equal(rec.anomalies[0].type, 'witness_failed')
  assert.equal(rec.anomalies[0].sequence, 2)
  assert.equal(JSON.stringify(rec.anomalies[0]).includes('Mara'), false, 'the anomaly carries no text')
})

// ── 3. language off: English path, no copy, no witness ─────────────────────
await check('language off: replay makes no copy and clears any stale witness', async () => {
  reset({ eventWitness: { lang: 'pt', ai_response: 'OLD ENGLISH', player_input: 'OLD PLAYER' } })
  await memoryService.replayEvent(String(eventId), String(playerId))
  assert.equal(rec.witnessCalls.length, 0, 'no copy')
  assert.equal(witnessUnset(), true, 'the stale witness is removed')
  // `witness_status` was never set on this fixture; an absent key is not unset,
  // so a plain English replay writes the same document as before.
  assert.equal(eventRow().data.witness_status, undefined)
  assert.ok(rec.extractorCalls.every((call) => !call.opts.choiceLanguage), 'no split choice pass')
})

// ── 1b. the flow's language (§7 point 1) ───────────────────────────────────
await check('flow language: replay reads the save, edit prefers the event witness language', async () => {
  reset({ replyLanguage: 'pt', eventWitness: { lang: 'es', ai_response: 'EN: prosa', player_input: 'EN player' } })
  await memoryService.replayEvent(String(eventId), String(playerId))
  assert.ok(rec.witnessCalls[0].messages[0].content.includes('Brazilian Portuguese'), 'replay uses the save language')

  reset({ replyLanguage: 'pt', eventWitness: { lang: 'es', ai_response: 'EN: prosa', player_input: 'EN player', choices: [] } })
  await memoryService.editEvent(String(eventId), String(playerId), { ai_response: 'Otra prosa nativa.' })
  assert.ok(rec.witnessCalls[0].messages[0].content.includes('Spanish'), 'edit uses the witness language before the save')
})

// ── 4. English freeze (compared after the recorded snapshot) ───────────────
const EMIT = process.env.WITNESS_REPLAY_EMIT === '1'
const ENGLISH_PLAYER_TEXT = 'I lean on the doorframe.'
const ENGLISH_PROSE_TEXT = 'Mara enters the hall.'

await check('English replay: calls and writes match the HEAD snapshot', async () => {
  reset({ playerInput: ENGLISH_PLAYER_TEXT, aiResponse: ENGLISH_PROSE_TEXT, narration: REPLAY_ENGLISH })
  await memoryService.replayEvent(String(eventId), String(playerId))
  const snapshot = trace()
  if (EMIT) {
    console.log('EMIT_ENGLISH_REPLAY ' + JSON.stringify(snapshot))
    return
  }
  // The place note reached English turns after the freeze; it is the only change.
  const { PLACE_NOTE } = await import('../src/utils/prompt-builder')
  const text = JSON.stringify(snapshot)
  const noteLine = JSON.stringify(`${PLACE_NOTE}\n`).slice(1, -1)
  assert.equal(text.split(noteLine).length, 2, 'the replay prompt carries the note once')
  assert.deepEqual(JSON.parse(text.replace(noteLine, '')), FROZEN.replay)
})

await check('English edit: calls and writes match the HEAD snapshot', async () => {
  reset({ playerInput: ENGLISH_PLAYER_TEXT, aiResponse: ENGLISH_PROSE_TEXT })
  await memoryService.editEvent(String(eventId), String(playerId), { ai_response: 'A new English beat.' })
  const snapshot = trace()
  if (EMIT) {
    console.log('EMIT_ENGLISH_EDIT ' + JSON.stringify(snapshot))
    return
  }
  assert.deepEqual(snapshot, FROZEN.edit)
})

await check('English select: calls and writes match the HEAD snapshot', async () => {
  reset({
    playerInput: ENGLISH_PLAYER_TEXT,
    aiResponse: ENGLISH_PROSE_TEXT,
    variants: [baseVariant({ id: 'alternative', narrative: 'Another English telling.', source: 'replay' })],
  })
  await memoryService.selectReplayVariant(String(eventId), String(playerId), 1)
  const snapshot = trace()
  if (EMIT) {
    console.log('EMIT_ENGLISH_SELECT ' + JSON.stringify(snapshot))
    return
  }
  assert.deepEqual(snapshot, FROZEN.select)
})

// ── 5. one view after a refusal with an old witness (edit) ─────────────────
await check('edit refused with an old witness: extraction reads native, witness cleared, event marked', async () => {
  reset({ replyLanguage: 'pt', eventWitness: { lang: 'pt', ai_response: 'OLD ENGLISH', player_input: 'OLD PLAYER', choices: [] } })
  witnessMode = 'refuse'
  await memoryService.editEvent(String(eventId), String(playerId), { ai_response: 'Nova prosa nativa.' })
  assert.equal(rec.extractorCalls[0].narrative, 'Nova prosa nativa.')
  assert.equal(rec.extractorCalls[0].opts.playerInput, NATIVE_PLAYER)
  assert.equal(witnessUnset(), true)
  assert.equal(witnessStatusSet(), 'failed')
  assert.equal(rec.anomalies[0].type, 'witness_failed')
})

// ── 6. player edit updates every variant's witness player text ─────────────
await check('player edit: the new English player text reaches the event and every variant', async () => {
  reset({
    replyLanguage: 'pt',
    eventWitness: { lang: 'pt', ai_response: 'STORED ENGLISH PROSE', player_input: NATIVE_PLAYER, choices: ENGLISH_CHOICES },
    variants: [baseVariant({ id: 'second', narrative: 'Outra prosa.', witness: { lang: 'pt', ai_response: 'EN: Outra prosa.', player_input: NATIVE_PLAYER } })],
  })
  witnessMode = 'accept'
  await memoryService.editEvent(String(eventId), String(playerId), { player_input: 'Novo texto nativo.' })
  const eventWitness = witnessSet()
  assert.equal(eventWitness.player_input, 'EN: Novo texto nativo.')
  assert.equal(eventWitness.ai_response, 'STORED ENGLISH PROSE', 'a player-only edit keeps the stored English prose')
  assert.deepEqual(eventWitness.choices, ENGLISH_CHOICES, 'a player-only edit keeps the stored chips')
  const variants = eventUpdate().$set['data.replay_variants']
  assert.equal(variants[0].witness.player_input, 'EN: Novo texto nativo.')
  assert.equal(variants[1].witness.player_input, 'EN: Novo texto nativo.')
  assert.equal(eventUpdate().$set['data.ai_response'], NATIVE_PROSE, 'the prose did not move')

  // A refused player copy invalidates every variant's witness too, and the
  // event, because the player text they were built from changed.
  reset({
    replyLanguage: 'pt',
    eventWitness: { lang: 'pt', ai_response: NATIVE_PROSE, player_input: NATIVE_PLAYER, choices: ENGLISH_CHOICES },
    variants: [baseVariant({ id: 'second', narrative: 'Outra prosa.', witness: { lang: 'pt', ai_response: 'EN: Outra prosa.', player_input: NATIVE_PLAYER } })],
  })
  witnessMode = 'refuse'
  await memoryService.editEvent(String(eventId), String(playerId), { player_input: 'Outro texto nativo.' })
  const refusedVariants = eventUpdate().$set['data.replay_variants']
  assert.equal('witness' in refusedVariants[0], false, 'the base variant loses its witness')
  assert.equal(refusedVariants[0].witness_status, 'failed')
  assert.equal('witness' in refusedVariants[1], false, 'the second variant loses its witness')
  assert.equal(witnessUnset(), true)
  assert.equal(witnessStatusSet(), 'failed')
})

// ── 7. prose edit then select the base variant: its own witness returns ────
await check('prose edit then select base: the base witness is restored, never the edited prose copy', async () => {
  reset({ replyLanguage: 'pt', eventWitness: { lang: 'pt', ai_response: ENGLISH_PROSE, player_input: NATIVE_PLAYER, choices: ENGLISH_CHOICES } })
  await memoryService.editEvent(String(eventId), String(playerId), { ai_response: 'Prosa editada.' })
  const editedWitness = witnessSet()
  assert.equal(editedWitness.ai_response, 'EN: Prosa editada.')
  assert.equal(rec.extractorCalls[0].narrative, 'EN: Prosa editada.', 'the copy is made before the extraction')

  await memoryService.selectReplayVariant(String(eventId), String(playerId), 0)
  const restored = witnessSet()
  assert.equal(restored.ai_response, ENGLISH_PROSE, 'base witness, not the edited one')
  assert.equal(restored.player_input, NATIVE_PLAYER)
  assert.deepEqual(restored.choices, ENGLISH_CHOICES)
})

// ── 8. select a failed variant retries once ────────────────────────────────
await check('select after a failed copy: one new attempt, refused again stays failed', async () => {
  reset({
    replyLanguage: 'pt',
    variants: [baseVariant({ id: 'failed', narrative: 'Prosa falhada.', witness_status: 'failed' })],
  })
  witnessMode = 'refuse'
  await memoryService.selectReplayVariant(String(eventId), String(playerId), 1)
  assert.ok(rec.witnessCalls.length >= 1, 'one retry was attempted')
  assert.equal(witnessUnset(), true)
  assert.equal(witnessStatusSet(), 'failed')
  assert.equal(rec.anomalies[0].type, 'witness_failed')

  // Accepted next time: the witness is rebuilt.
  reset({
    replyLanguage: 'pt',
    variants: [baseVariant({ id: 'failed', narrative: 'Prosa falhada.', witness_status: 'failed' })],
  })
  witnessMode = 'accept'
  await memoryService.selectReplayVariant(String(eventId), String(playerId), 1)
  assert.equal(witnessSet().ai_response, 'EN: Prosa falhada.')
  assert.equal(statusUnset(), true)
  const retried = eventUpdate().$set['data.replay_variants'][1]
  assert.equal(retried.witness.ai_response, 'EN: Prosa falhada.', 'the variant keeps the copy it was retried for')
  assert.equal('witness_status' in retried, false)
})

// ── 9. replay of a continue uses the witness prose for recall ──────────────
await check('replay of a continue: the copy asks for prose only and recall embeds the witness prose', async () => {
  reset({
    replyLanguage: 'pt',
    playerInput: '',
    eventWitness: { lang: 'pt', ai_response: 'EN: the previous english prose', player_input: '' },
  })
  await memoryService.replayEvent(String(eventId), String(playerId))
  const witnessBody = rec.witnessCalls[0]
  const user = witnessBody.messages.find((m: Row) => m.role === 'user')!.content
  assert.equal(user.includes('<player>'), false, 'no player part on a continue')
  assert.deepEqual(witnessBody.responseSchema.required, ['prose'])
  // print-only call: the embedding text is the witness prose, not the empty one
  const ragCall = rec.ragCalls[0] || []
  assert.equal(ragCall[2], 'EN: the previous english prose')
})

// ── 10. a tapped choice's stored English is known before the copy ─────────
await check('tapped-choice turn: the stored English player text is reused, not retranslated', async () => {
  reset({
    replyLanguage: 'pt',
    eventWitness: { lang: 'pt', ai_response: ENGLISH_PROSE, player_input: 'Stored English player', choices: ENGLISH_CHOICES },
  })
  await memoryService.replayEvent(String(eventId), String(playerId))
  const user = rec.witnessCalls[0].messages.find((m: Row) => m.role === 'user')!.content
  assert.equal(user.includes('<player>'), false, 'the already-English player text is never sent')
  assert.equal(witnessSet().player_input, 'Stored English player')
  assert.ok(user.includes('Player: I ask about the tide.\nNarrator: The hall is quiet.'), 'the copy is told the turn before this one, never this one')
  assert.ok(user.includes('Player, this turn: Stored English player'), 'the known English player line is context')
  assert.ok(user.includes('<world>\nA lamplit harbour inn.'), 'the copy is told the world\'s words')
})

// ── 11. the repair path stays in the language ──────────────────────────────
await check('repair on a Portuguese reply: the prompt stays in Portuguese and the validation is language-aware', async () => {
  reset({ replyLanguage: 'pt', narration: 'Mara entra e diz "olá. *Ela sorri.' })
  await memoryService.replayEvent(String(eventId), String(playerId))
  const repair = rec.repairCalls[0]
  assert.ok(repair, 'the unbalanced marker must trigger the repair path')
  const prompt = repair.messages[0].content
  assert.ok(prompt.includes('The story prose is in Brazilian Portuguese. The rewrite must stay in Brazilian Portuguese; never translate it into English.'))
  assert.equal(prompt.includes('like "I missed you."'), false, 'the English sample is dropped')
  assert.equal(prompt.includes('Refer to them as "you"'), false, 'English pronouns are dropped')
})

// ── 12. the wire never carries the witness ────────────────────────────────
await check('wire payload: publicMediaEvent strips witness and witness_status from event, variant and snapshot', async () => {
  reset({ replyLanguage: 'pt' })
  const row = clone(eventRow())
  row.data.witness = { lang: 'pt', ai_response: 'EN', player_input: 'EN' }
  row.data.witness_status = 'failed'
  row.data.replay_variants[0].witness = { lang: 'pt', ai_response: 'EN', player_input: 'EN' }
  row.data.replay_variants[0].witness_status = 'failed'
  row.edit_history = [{ previous_data: { ai_response: 'old', witness: { lang: 'pt' }, witness_status: 'failed', replay_variants: [{ narrative: 'x', witness: { lang: 'pt' }, witness_status: 'failed' }] }, edited_at: new Date(0) }]
  const wire = publicMediaEvent(row)
  assert.equal('witness' in wire.data, false)
  assert.equal('witness_status' in wire.data, false)
  assert.equal('witness' in wire.data.replay_variants[0], false)
  assert.equal('witness_status' in wire.data.replay_variants[0], false)
  assert.equal('witness' in wire.edit_history[0].previous_data, false)
  assert.equal('witness' in wire.edit_history[0].previous_data.replay_variants[0], false)
})

if (fail > 0) {
  console.log(`\nwitness replay audit: ${pass} passed, ${fail} failed`)
  process.exit(1)
}

if (process.argv.includes('--bites')) {
  await runBites()
} else {
  console.log(`\nwitness replay audit: ${pass} passed, 0 failed`)
}

// ── bites ────────────────────────────────────────────────────────────────────
type Edit = [file: string, from: string, to: string]
type Mutation = { name: string; check: string; edits: Edit[] }

async function runBites() {
  const root = await mkdtemp(join(import.meta.dir, '.witness-replay-bites-'))
  const server = new URL('..', import.meta.url).pathname
  const AUDIT = 'scripts/witness-replay-audit.ts'
  const memory = 'src/services/memory.service.ts'
  const hygiene = 'src/utils/prose-hygiene.ts'
  const wire = 'src/services/media/events.ts'
  const witness = 'src/utils/witness.ts'

  const mutations: Mutation[] = [
    {
      name: '1 replay uses the event witness language instead of the save',
      check: 'flow language: replay reads the save, edit prefers the event witness language',
      edits: [[memory, 'const replyLanguageEntry = effectiveReplyLanguage(instance.reply_language)', 'const replyLanguageEntry = replyLanguageForEvent(event, instance)']],
    },
    {
      name: '1 edit ignores the event witness language',
      check: 'flow language: replay reads the save, edit prefers the event witness language',
      edits: [[memory, 'const editLanguageEntry = replyLanguageForEvent(event, editInstance)', 'const editLanguageEntry = effectiveReplyLanguage(editInstance?.reply_language)']],
    },
    {
      name: '4 edit extraction reads native, not the copy',
      check: 'prose edit then select base: the base witness is restored, never the edited prose copy',
      edits: [[memory, "const editViewNarrative = editAcceptedWitness ? editAcceptedWitness.prose : nextAiResponse || ''", "const editViewNarrative = nextAiResponse || ''"]],
    },
    {
      name: '8 the shared glossary drops graph-only people',
      check: 'replay accepted: every extractor reads the English copy and the witness is stored',
      edits: [[witness, '    ...(input.graphPeople || []),\n', '']],
    },
    {
      name: '2 replay reads the old witness after a refusal',
      check: 'replay refused: both extractors read native, the event witness is cleared and marked',
      edits: [[memory, 'const replayViewNarrative = replayAcceptedWitness ? replayAcceptedWitness.prose : repairedReplay.narrative', 'const replayViewNarrative = replayAcceptedWitness ? replayAcceptedWitness.prose : (witnessOf(event).ai_response || repairedReplay.narrative)']],
    },
    {
      name: '2 replay stores no witness on acceptance',
      check: 'replay accepted: every extractor reads the English copy and the witness is stored',
      edits: [[memory, "replayWitnessSet['data.witness'] = witnessEventFields({", "replayWitnessSet['data.not_witness'] = witnessEventFields({"]],
    },
    {
      name: '3 language off keeps a stale witness',
      check: 'language off: replay makes no copy and clears any stale witness',
      edits: [[memory, "if (event.data?.witness) replayWitnessUnset['data.witness'] = ''", 'void event.data']],
    },
    {
      name: '5 edit reads the old witness player after a refusal',
      check: 'edit refused with an old witness: extraction reads native, witness cleared, event marked',
      edits: [[memory, "const editViewPlayer = editAcceptedWitness ? editAcceptedWitness.player : nextPlayerInput || ''", "const editViewPlayer = event.data?.witness?.player_input || nextPlayerInput || ''"]],
    },
    {
      name: '6 player edit skips the variants',
      check: 'player edit: the new English player text reaches the event and every variant',
      edits: [[memory, 'return { ...variant, witness: { ...variant.witness, player_input: editAcceptedWitness.player } }', 'return variant']],
    },
    {
      name: '7 select keeps the edited witness',
      check: 'prose edit then select base: the base witness is restored, never the edited prose copy',
      edits: [[memory, "if (changed) {\n      if (chosenWitness) {", 'if (false) {\n      if (chosenWitness) {']],
    },
    {
      name: '9 continue embedding uses the native empty text',
      check: 'replay of a continue: the copy asks for prose only and recall embeds the witness prose',
      edits: [[memory, 'parsed.raw || witnessOf(event).ai_response || template.seed_prompt', 'parsed.raw || event.data.ai_response || template.seed_prompt']],
    },
    {
      name: '10 tapped choice is retranslated',
      check: 'tapped-choice turn: the stored English player text is reused, not retranslated',
      edits: [[memory, "replayStoredWitness && replayStoredWitness.lang === replayWitnessLanguage.code", 'false']],
    },
    {
      name: '10c the world words never reach the copy',
      check: 'tapped-choice turn: the stored English player text is reused, not retranslated',
      edits: [[memory, '...(params.worldContext ? { worldContext: params.worldContext } : {}),', '']],
    },
    {
      name: '10b the turn before is this turn',
      check: 'tapped-choice turn: the stored English player text is reused, not retranslated',
      edits: [[memory, 'sequence: { $lt: Number(params.event?.sequence || 0) }', 'sequence: { $lte: Number(params.event?.sequence || 0) }']],
    },
    {
      name: '11 repair prompt has no language rule',
      check: 'repair on a Portuguese reply: the prompt stays in Portuguese and the validation is language-aware',
      edits: [[hygiene, '`- The story prose is in ${replyLanguageName}. The rewrite must stay in ${replyLanguageName}; never translate it into English.\\n`', "''"]],
    },
    {
      name: '12 the wire keeps the witness',
      check: 'wire payload: publicMediaEvent strips witness and witness_status from event, variant and snapshot',
      edits: [[wire, '  delete data.witness\n', '']],
    },
    {
      name: '6b a refused player copy keeps the variants witness',
      check: 'player edit: the new English player text reaches the event and every variant',
      edits: [[memory, "return { ...copy, witness_status: 'failed' as const }", 'return { ...copy, witness: variant.witness }']],
    },
    {
      name: '4b a player-only edit replaces the stored English prose',
      check: 'player edit: the new English player text reaches the event and every variant',
      edits: [[memory, 'prose: playerChanged && !aiChanged && storedEditWitness ? storedEditWitness.ai_response : accepted.prose', 'prose: accepted.prose']],
    },
    {
      name: '8c the retried variant forgets its copy',
      check: 'select after a failed copy: one new attempt, refused again stays failed',
      edits: [[memory, 'if (changed && chosenFailed && selectWitnessLanguage && selectAcceptedWitness) {', 'if (false) {']],
    },
    {
      name: '8b select does not retry a failed variant',
      check: 'select after a failed copy: one new attempt, refused again stays failed',
      edits: [[memory, 'if (changed && chosenFailed && selectWitnessLanguage && selectedInstance) {', 'if (false) {']],
    },
  ]

  try {
    await cp(join(server, 'src'), join(root, 'src'), { recursive: true })
    await cp(join(server, 'worker'), join(root, 'worker'), { recursive: true })
    await mkdir(join(root, 'scripts'), { recursive: true })
    await cp(join(server, AUDIT), join(root, AUDIT))
    await symlink(join(server, 'node_modules'), join(root, 'node_modules'), 'dir')

    const runAudit = async () => {
      const child = Bun.spawn(['bun', '--no-env-file', 'run', AUDIT], {
        cwd: root,
        env: { ...process.env, NODE_ENV: 'test' },
        stdout: 'pipe',
        stderr: 'pipe',
        stdin: 'ignore',
      })
      const timer = setTimeout(() => child.kill(9), 120_000)
      const [stdout, stderr, code] = await Promise.all([
        new Response(child.stdout).text(),
        new Response(child.stderr).text(),
        child.exited,
      ])
      clearTimeout(timer)
      return { stdout, stderr, code }
    }

    const clean = await runAudit()
    assert.equal(clean.code, 0, `the unmutated copy must pass:\n${clean.stdout}\n${clean.stderr}`)
    console.log(`baseline: clean copy passes (${(clean.stdout.match(/^  ok /gm) ?? []).length} checks)`)

    let bitten = 0
    for (const mutation of mutations) {
      const originals = new Map<string, string>()
      try {
        for (const [file, from, to] of mutation.edits) {
          const path = join(root, file)
          const text = originals.get(path) ?? (await readFile(path, 'utf8'))
          originals.set(path, text)
          assert.ok(text.includes(from), `${mutation.name}: mutation anchor missing: ${from}`)
          await writeFile(path, text.replaceAll(from, to))
        }
        const result = await runAudit()
        assert.notEqual(result.code, 0, `${mutation.name}: the audit accepted the broken behaviour\n${result.stdout}`)
        assert.ok(
          `${result.stdout}${result.stderr}`.includes(`FAIL ${mutation.check}`),
          `${mutation.name}: failed outside the intended check\n${result.stdout}\n${result.stderr}`,
        )
        bitten++
        console.log(`BITE ${mutation.name}: exit ${result.code}; FAIL ${mutation.check}`)
      } finally {
        for (const [path, original] of originals) await writeFile(path, original)
      }
    }
    console.log(`witness replay bites: ${bitten}/${mutations.length} mutations rejected; scratch restored and removed`)
    if (bitten !== mutations.length) process.exit(1)
  } finally {
    await rm(root, { recursive: true, force: true })
  }
}
